preConditionHook:
// GRIMES'S NAMED "PULLBACK, ENTERING LOWER TIME FRAME BREAKOUT" TEMPLATE
// (G06-26), carried as the book states it and with its parts INLINED. The same
// pullback setup as the Pullback template, but TIMED BY A BREAKOUT OUT OF THE
// PULLBACK instead of by a bounce into it: better momentum confirmation, worse
// trade location and a larger stop, which is the trade-off the book draws.
//
// THREE PARTS:
//   1. A STRONG SETUP LEG (ExtensionLegExceedsSetupLeg, G06-14).
//   2. A QUIET PULLBACK (PullbackRangeBelowLegRange, G06-15).
//   3. A TRIGGER: the closing price clears the highest high of the last
//      ltfLookback bars ending one bar ago (LowerTimeFrameBreakoutEntry,
//      G06-22) **OR** it clears a run of bars that shared the same high
//      (EqualHighsBreakout, G06-23). THIS OR IS WHY THE TEMPLATE IS ONE FILE.
//
// THE THIRD `depends_on_keys` ENTRY RESOLVED: LowerTimeFrameBreakoutEntry is a
// merge working name that appears in no slice. The merged breakouts bucket
// carries G06-22 as CloseAbovePriorHighestHigh at lookback 3, marked a
// DUPLICATE of that catalog rule and never authored, so the trigger is that
// rule's condition inlined with its lookback as ltfLookback. The lower time
// frame is merge decision 4's multiplier read DOWNWARD -- a 3-bar breakout on
// the trading timeframe standing in for a several-times-faster chart; Grimes
// gives no ratio.
//
// PART 3 IS NOT REACHABLE AS PANES for the same reason part 4 of the Pullback
// template is not: entry panes AND, and this is an OR of two triggers. The
// setup halves ARE separately placeable, but only ALONGSIDE the OR, which is
// what a single file gives.
//
// NO ATR HERE. The equal-highs tolerance is in TICKS, which is
// EqualHighsBreakout's own spelling (MinMove and PriceScale are VERIFIED, and a
// tick margin is written division-first, toleranceTicks * (MinMove/PriceScale));
// the level tolerances that decision 7 puts in ATR fractions are the ones this
// template does not use, because both triggers clear a level outright rather
// than testing a touch of one.
//
// MEASURED SWING PIVOT (decision 14, EL_Swing_Probe.txt): occurrences 1 and 2
// only, since occurrence 3+ is UNMEASURED; MIXED tie sense -- AT OR BEYOND the
// swingStrength OLDER bars, STRICTLY BEYOND the swingStrength NEWER bars -- lag
// exactly swingStrength bars, and the -1 SENTINEL GUARDED ON THE BAR INDEX,
// never on the returned price. THE ORDERING GUARD is
// ExtensionLegExceedsSetupLeg's: bars-ago counts descend
// loBar2 > hiBar1 > loBar1 on the long side with setupUp > 0.
//
// For GUARDS at >= 1 on the two range loops and at >= 2 on the equal-bars scan:
// EasyLanguage's For counts DOWN when the end value is below the start, so
// `for kk = 0 to -1` would read the NEXT bar and `for kk = 2 to 1` would walk
// the equal-highs window backwards, where the C++ for-loops would not run at
// all. The two means are guarded against a zero divisor the same way.
//
// SHIFT TEST: leg lengths and bar ranges are price DIFFERENCES, the equality
// band is a tick margin, and both triggers compare a price with a window
// extreme of the same series.
//
// Deepest bar touched: max(pivotLookback - 1 + swingStrength,
// pullbackBars + legBars - 1, ltfLookback, equalBarsCount).
//
// THE C++ TWIN WRITES OUT BY HAND what the EL twin says with built-ins.
// Highest/Lowest bottom out in Extremes(), EL SOURCE, so each window is a scan
// SEEDED ON THE WINDOW'S FIRST BAR and continued with a STRICT comparison under
// the EL relational tolerance (el_gt / el_lt). The pivot scan is
// ExtensionLegExceedsSetupLeg's inlined form, written WITHOUT break and with
// the < 2 counters so occurrences 1 and 2 land in the slots the EL twin's
// Occurrence arguments do.
//
// Every scratch value is a localVariables entry rather than a hook-scope
// declaration, so the hooks survive a double placement; loop counters and
// per-candidate flags are block-scoped inside their loops.
nHi = 0;
nLo = 0;
hiPx1 = -1.0;
hiBar1 = -1.0;
hiPx2 = -1.0;
hiBar2 = -1.0;
loPx1 = -1.0;
loBar1 = -1.0;
loPx2 = -1.0;
loBar2 = -1.0;
for (int j = (int)swingStrength; j <= (int)pivotLookback - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - (int)swingStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + (int)swingStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHi < 2) {
        nHi = nHi + 1;
        if (nHi == 1) { hiPx1 = high[j]; hiBar1 = (double)j; }
        if (nHi == 2) { hiPx2 = high[j]; hiBar2 = (double)j; }
    }
    if (okLo && nLo < 2) {
        nLo = nLo + 1;
        if (nLo == 1) { loPx1 = low[j]; loBar1 = (double)j; }
        if (nLo == 2) { loPx2 = low[j]; loBar2 = (double)j; }
    }
}
setupUp = hiPx1 - loPx2;
runUp = close[0] - loPx1;
setupDn = hiPx2 - loPx1;
runDn = hiPx1 - close[0];
legUp = (loBar1 != -1.0) && (loBar2 != -1.0) && (hiBar1 != -1.0)
    && el_gt(loBar2, hiBar1) && el_gt(hiBar1, loBar1) && el_gt(setupUp, 0.0)
    && el_ge(runUp, extensionRatio * setupUp);
legDn = (hiBar1 != -1.0) && (hiBar2 != -1.0) && (loBar1 != -1.0)
    && el_gt(hiBar2, loBar1) && el_gt(loBar1, hiBar1) && el_gt(setupDn, 0.0)
    && el_ge(runDn, extensionRatio * setupDn);
pbSum = 0.0;
for (int kk = 0; kk <= (int)pullbackBars - 1; ++kk) {
    pbSum = pbSum + (high[kk] - low[kk]);
}
legSum = 0.0;
for (int kk = (int)pullbackBars; kk <= (int)pullbackBars + (int)legBars - 1; ++kk) {
    legSum = legSum + (high[kk] - low[kk]);
}
pbMean = 0.0;
legMean = 0.0;
if ((int)pullbackBars >= 1) pbMean = pbSum / (int)pullbackBars;
if ((int)legBars >= 1) legMean = legSum / (int)legBars;
quiet = el_lt(pbMean, reducedFraction * legMean);
ltfHi = high[1];
ltfLo = low[1];
for (int i = 2; i <= (int)ltfLookback; ++i) {
    if (el_gt(high[i], ltfHi)) ltfHi = high[i];
    if (el_lt(low[i], ltfLo)) ltfLo = low[i];
}
tickSize = ctx.MinMove() / ctx.PriceScale();
eqHi = true;
eqLo = true;
lvlHi = high[1];
lvlLo = low[1];
for (int kk = 2; kk <= (int)equalBarsCount; ++kk) {
    if (el_gt(std::fabs(high[kk] - high[1]), toleranceTicks * tickSize)) eqHi = false;
    if (el_gt(std::fabs(low[kk] - low[1]), toleranceTicks * tickSize)) eqLo = false;
    if (el_gt(high[kk], lvlHi)) lvlHi = high[kk];
    if (el_lt(low[kk], lvlLo)) lvlLo = low[kk];
}
trigUp = el_gt(close[0], ltfHi) || (eqHi && el_gt(close[0], lvlHi));
trigDn = el_lt(close[0], ltfLo) || (eqLo && el_lt(close[0], lvlLo));
